function validate([n, firstPlayer, secondPlayer]) {
  if (!Number.isInteger(n) || n < 2 || n > 28) return 'n must be between 2 and 28.';
  if (!Number.isInteger(firstPlayer) || !Number.isInteger(secondPlayer)) return 'Players are whole numbers.';
  if (firstPlayer < 1 || secondPlayer > n || firstPlayer >= secondPlayer) return 'Need 1 <= firstPlayer < secondPlayer <= n.';
  return null;
}

