function earliestAndLatest(n, firstPlayer, secondPlayer) {
  const memo = new Map();

  const solve = (count, first, second) => {
    if (first + second === count + 1) {
      return [1, 1];
    }
    if (first + second > count + 1) {
      return solve(count, count + 1 - second, count + 1 - first);
    }
    const key = count * 1024 + first * 32 + second;
    if (memo.has(key)) {
      return memo.get(key);
    }
    const next = (count + 1) >> 1;
    const mirror = count + 1 - second;
    const between = second <= next ? second - first - 1 : mirror - first - 1;
    const fixed = second <= next ? 0 : (second - mirror) >> 1;
    let earliest = Infinity;
    let latest = 0;
    for (let left = 0; left < first; left++) {
      for (let middle = 0; middle <= between; middle++) {
        const [low, high] = solve(next, left + 1, left + middle + fixed + 2);
        earliest = Math.min(earliest, low + 1);
        latest = Math.max(latest, high + 1);
      }
    }
    const result = [earliest, latest];
    memo.set(key, result);
    return result;
  };

  return solve(n, firstPlayer, secondPlayer);
}

