function earliestAndLatest(n, firstPlayer, secondPlayer) {
  const star = p => p === firstPlayer || p === secondPlayer;
  const cache = new Map();
  const play = row => {
    const key = row.join(',');
    if (cache.has(key)) return cache.get(key);
    const half = Math.floor(row.length / 2);
    const kept = [], open = [];
    for (let k = 0; k < half; k++) {
      const a = row[k], b = row[row.length - 1 - k];
      if (star(a) && star(b)) { cache.set(key, [1, 1]); return [1, 1]; }
      if (star(a)) kept.push(a);
      else if (star(b)) kept.push(b);
      else open.push([a, b]);
    }
    if (row.length % 2 === 1) kept.push(row[half]);
    let lo = Infinity, hi = -Infinity;
    for (let mask = 0; mask < (1 << open.length); mask++) {
      const nextRow = kept.concat(open.map(([a, b], i) => (mask >> i) & 1 ? a : b)).sort((x, y) => x - y);
      const [x, y] = play(nextRow);
      lo = Math.min(lo, x + 1);
      hi = Math.max(hi, y + 1);
    }
    cache.set(key, [lo, hi]);
    return [lo, hi];
  };
  return play(Array.from({ length: n }, (_, i) => i + 1));
}

