function generate(rand, size) {
  const n = size === 'large' ? 20 + Math.floor(rand() * 9) : 2 + Math.floor(rand() * 12);
  const firstPlayer = 1 + Math.floor(rand() * (n - 1));
  const secondPlayer = firstPlayer + 1 + Math.floor(rand() * (n - firstPlayer));
  return [n, firstPlayer, secondPlayer];
}
